## Submitted testbench
```systemverilog
module tb;

  // Parameters
  localparam int CLK_PERIOD = 8;
  localparam logic [15:0] PRESCALE_VAL = 16'd5;

  // Clock and reset
  logic clk = 0;
  logic rst = 1;
  logic [15:0] prescale = PRESCALE_VAL;

  // UART_RX interface signals
  logic rxd = 1'b1;
  logic m_axis_tready = 1'b1;
  logic m_axis_tvalid;
  logic [7:0] m_axis_tdata;
  logic busy;
  logic overrun_error;
  logic frame_error;

  // Instantiate uart_rx
  uart_rx #(.DATA_WIDTH(8)) dut (
    .clk(clk),
    .rst(rst),
    .m_axis_tdata(m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd(rxd),
    .busy(busy),
    .overrun_error(overrun_error),
    .frame_error(frame_error),
    .prescale(prescale)
  );

  // Clock generation
  always #(CLK_PERIOD/2) clk = ~clk;

  // Reset sequence
  initial begin
    rst = 1;
    #100;
    rst = 0;
    #200;
  end

  // Task to wait a bit period based on prescale
  task automatic wait_bit_cycles;
    int cnt;
    int bcs;
    bcs = int'(prescale) * 8;
    cnt = 0;
    while (cnt < bcs) begin
      @(posedge clk);
      cnt = cnt + 1;
    end
  endtask

  // Send two bytes (0x3C then 0xA5) on rxd
  initial begin
    // Wait for reset deassertion
    @(negedge rst);
    #10;

    // ---- Byte 0x3C ----
    rxd = 0;
    wait_bit_cycles;
    for (int i=0; i<8; i=i+1) begin
      rxd = (8'h3C >> i) & 8'h1;
      wait_bit_cycles;
    end
    rxd = 1;
    wait_bit_cycles;

    // ---- Byte 0xA5 ----
    rxd = 0;
    wait_bit_cycles;
    for (int i=0; i<8; i=i+1) begin
      rxd = (8'hA5 >> i) & 8'h1;
      wait_bit_cycles;
    end
    rxd = 1;
    wait_bit_cycles;

    // Wait for coverage point to be hit
    repeat (2000) @(posedge clk);

    // End simulation
    $finish;
  end

endmodule
```

